function stripAccents(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function normalize(s) {
  return stripAccents(String(s || '').toLowerCase())
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function hasAnyWord(text, words) {
  const set = new Set(text.split(' ').filter(Boolean));
  return words.some(w => set.has(w));
}

function hasAnyPhrase(text, phrases) {
  return phrases.some(p => text.includes(p));
}

// 1) lee mensaje del usuario
const raw = $json.concat_message ?? '';
const msg = normalize(raw);

// 2) diccionarios
const negativeWords = [
  'no', 'nop', 'nopi', 'nunca', 'jamas', 'jamás', 'negativo', 'rechazo', 'deniego', 'cancela', 
  'cancelar', 'niet', 'nanay', 'ninguno', 'ninguna', 'falso', 'incorrecto', 'parar', 'detener'
];

const negativePhrases = [
  'no acepto', 'no deseo', 'no quiero', 'gracias no', 'no gracias', 'como asi',
  'ni loco', 'ni de broma', 'de ninguna manera', 'en absoluto', 'paso de esto',
  'no me interesa', 'para nada', 'ahora no', 'en otro momento', 'no autorizo',
  'no estoy de acuerdo', 'me niego', 'no doy permiso'
];

const affirmativeWords = [
  'si', 'sí', 'sip', 'sipp', 'ok', 'oki', 'okay', 'okei', 'dale', 'listo', 'va', 'vamos', 'deacuerdo',
  'correcto', 'confirmo', 'confirmado', 'acepto', 'claro', 'perfecto', 'bien', 'bueno', 'buenisimo',
  'continuar', 'continua', 'continuemos', 'autorizo', 'autorizado', 'aceptar', 'amen', 'afirmativo',
  'adelante', 'proceda', 'procede', 'entendido', 'comprendido', 'asiento', 'concedo'
];

const affirmativePhrases = [
  'si acepto', 'acepto continuar', 'acepto los terminos', 'acepto terminos',
  'acepto condiciones', 'de acuerdo', 'esta bien', 'ok acepto', 'si continuo', 'de una',
  'estoy de acuerdo', 'doy mi consentimiento', 'proceder con el registro', 'me parece bien',
  'si por favor', 'adelante con ello', 'claro que si', 'por supuesto', 'sin problema'
];

// 3) eval
const isNegative = hasAnyPhrase(msg, negativePhrases) || hasAnyWord(msg, negativeWords);

let isAffirmative = false;
if (!isNegative) {
  isAffirmative = hasAnyPhrase(msg, affirmativePhrases) || hasAnyWord(msg, affirmativeWords);
}

// Mensajes ultra cortos tipo "ok", "si"
const wc = msg ? msg.split(' ').length : 0;
if (!isNegative && !isAffirmative && wc <= 2) {
  if (['si','ok','okay','listo','dale','va'].includes(msg)) isAffirmative = true;
}

const isUnknown = !isNegative && !isAffirmative;

// 4) IMPORTANTe: no “mientas” aquí al agente.
// Solo setea flags. La actualización REAL se hace en el nodo Update Contact.
return [
  {
    json: {
      ...$json,
      consent_eval: {
        raw,
        normalized: msg,
        is_affirmative: isAffirmative,
        is_negative: isNegative,
        is_unknown: isUnknown,
      }
    }
  }
];

const out = { ...$json };

// Asegura existencia de la estructura
out.contact_context = out.contact_context || {};
out.contact_context.custom_attributes = out.contact_context.custom_attributes || {};

// Setea SOLO el atributo necesario
out.contact_context.custom_attributes.terms_accepted = true;
out.contact_context.custom_attributes.terms_accepted_at =
out.contact_context.custom_attributes.terms_accepted_at ?? new Date().toISOString();
out.contact_context.tac = true;
out.contact_context.tac_accepted_at =
out.contact_context.tac_accepted_at ?? new Date().toISOString();

return [{ json: out }];

const concat = String($json.concat_message ?? '');
const pending = String($json.pending_intent_block ?? '');
const contact = $json.contact_context ?? {};
const convo = $json.conversation ?? {};

const content =
`<<<USER_UTTERANCE>>>
${concat}
<<<END_USER_UTTERANCE>>>

<<<PENDING_INTENT_BLOCK>>>
${pending}
<<<END_PENDING_INTENT_BLOCK>>>

<<<CONTACT_CONTEXT_JSON>>>
${JSON.stringify(contact, null, 2)}
<<<END_CONTACT_CONTEXT_JSON>>>

<<<CONVERSATION_CONTEXT_JSON>>>
${JSON.stringify(convo, null, 2)}
<<<END_CONVERSATION_CONTEXT_JSON>>>`;

const memoryObj = {
  type: "human",
  content,
  additional_kwargs: {},
  response_metadata: {}
};

// IMPORTANTE: guardamos ambas versiones para que el insert sea fácil
return [{
  json: {
    ...$json,
    memory_message_obj: memoryObj,
    memory_message_text: JSON.stringify(memoryObj) // por si tu columna es TEXT
  }
}];

const senderType = String(
  $json.body?.conversation?.messages?.[0]?.sender_type || ''
).toLowerCase();

const isUserMessage =
  $json.body?.event === 'message_created' &&
  (senderType === 'contact' || senderType === 'user');

return [{
  json: {
    ...$json,
    is_user_message: isUserMessage,
    _debug: {
      event: $json.body?.event,
      sender_type: senderType
    }
  }
}];
